import './js/vue.2.7.4/vue.min.js'
import Element from 'element-ui'
import * as $ from './js/recovery/jquery-3.6.0.min.js'

import('./elementUiCss/ele_index.css')

// 添加控制rem的html元素的style="font-size: 100px"
document.documentElement.style.fontSize = '100px'
document.body.style.fontSize = '16px'

Vue.use(Element)
// 设置Element UI的语言为中文
// ELEMENT.locale(ELEMENT.lang.zhCN)
new Vue({
  el: '#app',
  data() {
    return {
      uploadData: {
        bucketType: 'public'
      },
      searchForm: {
        name: '',
        displayName: '',
        jarFile: '',
        viewFile: ''
      },
      totalCount: 0,
      pageSize: 10,
      currentPage: 1,
      expand: true, // 默认展开显示操作步骤
      baseUrl: '',
      uploadUrl: '',
      uploadHeaders: '',
      token: '',
      tokenStorage: '',
      columns: [
        {
          title: '序号',
          type: 'index',
          width: 80,
          align: 'center'
        },
        {
          title: '应用',
          key: 'name',
          align: 'center'
        },
        {
          title: '名称',
          key: 'display_name',
          align: 'center'
        },
        {
          title: '版本',
          key: 'version',
          align: 'center'
        },
        {
          title: '前端压缩包',
          key: 'view_file',
          align: 'center'
        },
        {
          title: '应用jar包',
          key: 'jar_file',
          align: 'center'
        }
      ],
      tableHeight: '500',
      // 表格数据
      tableData: [],
      // 选中的行
      multipleSelection: [],
      // 加载状态
      loading: false,
      // 上传弹窗显示状态
      uploadDialogVisible: false,
      // 上传表单数据
      uploadForm: {
        id: null,
        viewFileId: null,
        viewFileName: '',
        jarFileId: null,
        jarFileName: '',
        display_name: '',
        state: '',
        source: '',
        name: ''
      },
      viewFileLoading: false,
      jarFileLoading: false,
      // 不可选行的ID数组
      unselectableRowIds: []
    }
  },
  mounted() {
    this.$nextTick(() => {
      // 阻止表格全选事件
      const checkbox = document.querySelector('.el-table__header .el-checkbox')
      checkbox.parentNode.style.cursor = 'not-allowed'
      if (checkbox) {
        checkbox.addEventListener(
          'click',
          function (e) {
            e.stopPropagation()
            e.preventDefault()
          },
          true
        )
      }
    })
  },
  created() {
    let that = this
    this.setUploadGroupsMaxHeight()
    // 窗口大小变化时重新计算高度
    $(window).on('resize', function () {
      that.setUploadGroupsMaxHeight()
    })
    this.baseUrl = window.location.origin + '/api'
    let tempApi = ''
    if (sessionStorage) {
      tempApi = sessionStorage.getItem('tempApi')
    }
    this.baseUrl = tempApi || this.baseUrl
    this.uploadUrl = this.baseUrl + '/recovery/app/upload'
    this.token = localStorage.getItem('recovery_token')
    if (this.token) {
      this.setToken()
    } else {
      this.$message({
        type: 'warning',
        message: '请先配置秘钥并提交'
      })
    }
  },
  methods: {
    // 切换每页条数
    handleSizeChange(val) {
      this.pageSize = val
      this.fetchData()
    },
    // 切换页码
    handleCurrentChange(val) {
      this.currentPage = val
      this.fetchData()
    },
    // 重置查询
    resetSearch() {
      this.searchForm = {
        name: '',
        displayName: '',
        jarFile: '',
        viewFile: ''
      }
      this.fetchData()
    },
    // 展开显示操作步骤
    toExpand() {
      this.expand = !this.expand
      if (!this.expand) {
        document.getElementById('tips-container').style.height = '70px'
        document.getElementById('tips-container').style.overflow = 'hidden'
      } else {
        document.getElementById('tips-container').style.height = ''
        document.getElementById('tips-container').style.overflow = ''
      }
      this.setUploadGroupsMaxHeight()
    },
    // 设置表格最大高度
    setUploadGroupsMaxHeight(value) {
      const viewportHeight = window.scrollY || window.innerHeight // 获取视口高度
      if (viewportHeight < 500) return
      const customHeight = this.expand ? 450 : 280 // 预留空间
      this.tableHeight = viewportHeight - customHeight // 计算最大高度
    },
    handleClearToken() {
      this.tokenStorage = this.token = ''
      this.fetchData()
      this.uploadHeaders = {
        Authorization: this.tokenStorage
      }
      localStorage.setItem('recovery_token', this.token)
    },
    setToken() {
      if (this.token.startsWith('Bearer ')) {
        this.tokenStorage = this.token
      } else {
        this.tokenStorage = 'Bearer ' + this.token
      }
      this.fetchData()
      this.uploadHeaders = {
        Authorization: this.tokenStorage
      }
      localStorage.setItem('recovery_token', this.token)
    },
    // 判断行是否可选
    isSelectable(row) {
      // 如果行ID在不可选数组中，则不可选
      return !this.unselectableRowIds.includes(row.id)
    },
    // 批量设置行是否可选
    setRowsSelectable(rowIds, selectable) {
      if (selectable) {
        // 批量设置为可选
        this.unselectableRowIds = this.unselectableRowIds.filter(
          (item) => !rowIds.includes(item.id)
        )
      } else {
        // 批量设置为不可选
        rowIds.forEach((item) => {
          if (!this.unselectableRowIds.includes(item.id)) {
            this.unselectableRowIds.push(item.id)
          }
        })
      }
    },
    // 批量设置可选
    handleSelectionChange(val) {
      if (val.length > 0) {
        if (val[0].type === 'server-base' || val[0].type === 'front-base') {
          let ids = this.tableData.filter((item) => item.id !== val[0].id)
          this.setRowsSelectable(ids, false)
          this.setRowsSelectable([val[0].id], true)
        } else {
          let ids = this.tableData.filter(
            (item) => item.type !== 'server-base' && item.type !== 'front-base'
          )
          let baseIds = this.tableData.filter(
            (item) => item.type == 'server-base' || item.type == 'front-base'
          )
          this.setRowsSelectable(ids, true)
          this.setRowsSelectable(baseIds, false)
        }
      } else {
        this.unselectableRowIds = []
      }
      this.multipleSelection = val
    },
    // 获取表格数据
    async fetchData() {
      this.loading = true
      let that = this
      let params = JSON.stringify({
        page: this.currentPage,
        pageSize: this.pageSize,
        ...this.searchForm
      })
      $.ajax({
        url: this.baseUrl + '/recovery/app',
        method: 'POST',
        data: params,
        headers: {
          'Content-Type': 'application/json',
          Authorization: that.tokenStorage
        },
        success: function (response) {
          if (response?.error) {
            that.$message.error(response?.error?.message)
          } else {
            that.tableData = response?.result?.data
            that.totalCount = response?.result?.totalCount || 0
            that.currentPage = that.totalCount < that.pageSize ? 1 : that.currentPage
          }
          that.loading = false
        },
        error: function (xhr, status, error) {
          that.$message.error(error)
          that.loading = false
        },
        finally: function () {
          that.loading = false
        }
      })
    },
    //  批量恢复
    batchRecovery() {
      if (this.multipleSelection.length == 0) {
        this.$message({
          type: 'warning',
          message: '请选择要恢复的项'
        })
        return
      }
      let ids = []
      for (let i = 0; i < this.multipleSelection.length; i++) {
        ids.push(this.multipleSelection[i].id)
      }
      let that = this
      this.loading = true
      let appIds = JSON.stringify({ appIds: ids })
      $.ajax({
        url: this.baseUrl + '/recovery/app/batch-recovery',
        method: 'POST',
        data: appIds,
        headers: {
          'Content-Type': 'application/json',
          Authorization: that.tokenStorage
        },
        success: function (response) {
          if (response?.error) {
            that.$message.error(response?.error?.message)
          } else {
            that.$message.success('操作成功')
          }
          that.loading = false
        },
        error: function (xhr, status, error) {
          that.$message.error(error)
          that.loading = false
        },
        finally: function () {
          that.loading = false
        }
      })
    },
    uninstall(row) {
      let that = this
      this.$confirm(`确认要卸载${row.name}?`)
        .then(() => {
          that.loading = true
          let appIds = JSON.stringify({ appIds: [row.id] })
          $.ajax({
            url: that.baseUrl + '/recovery/app/uninstall',
            method: 'POST',
            data: appIds,
            headers: {
              'Content-Type': 'application/json',
              Authorization: that.tokenStorage
            },
            success: function (response) {
              if (response?.error) {
                that.$message.error(response?.error?.message)
              } else {
                that.$message.success('卸载成功')
                that.fetchData()
              }
              that.loading = false
            },
            error: function (xhr, status, error) {
              that.$message.error(error)
              that.loading = false
            },
            finally: function () {
              that.loading = false
            }
          })
        })
        .catch(() => {
          this.$message({
            type: 'info',
            message: '已取消卸载'
          })
        })
    },
    upload(row) {
      let that = this
      $.ajax({
        url: this.baseUrl + '/recovery/app/' + row.id,
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
          Authorization: that.tokenStorage
        },
        success: function (response) {
          if (response?.error) {
            that.$message.error(response?.error?.message)
          } else {
            that.uploadForm = response?.result?.data[0]
            that.uploadForm.jarFileName = response?.result?.data[0].jar_file
            that.uploadForm.viewFileName = response?.result?.data[0].view_file
            that.uploadForm.jarFileId = response?.result?.data[0].jar_file_id
            that.uploadForm.viewFileId = response?.result?.data[0].view_file_id
            that.uploadDialogVisible = true
          }
        },
        error: function (xhr, status, error) {
          that.$message.error(error)
        }
      })
    },
    beforeViewUpload() {
      this.viewFileLoading = true
    },
    // 前端包zip文件上传成功
    handleAvatarSuccess(response, file, fileList) {
      if (response.error) {
        this.$message.error(`上传失败: ${response.error.message}`)
      } else {
        this.uploadForm = {
          ...this.uploadForm,
          viewFileId: response.result?.data?.[0]?.id || null,
          viewFileName: response.result?.data?.[0]?.name || null
        }
      }
      this.viewFileLoading = false
      // 重置上传组件
      this.$nextTick(() => {
        this.$refs.viewUpload && this.$refs.viewUpload.clearFiles()
      })
    },
    // 前端包zip上传失败
    handleAvatarError(err, file, fileList) {
      this.$message.error('上传失败' + err.error)
      this.viewFileLoading = false
    },
    beforeJarUpload() {
      this.jarFileLoading = true
    },
    // 后端jar包上传失败
    handleJarError(err, file, fileList) {
      this.$message.error('上传失败' + err.error)
      this.jarFileLoading = false
    },
    // 后端jar包上传成功
    handleJarSuccess(response, file, fileList) {
      if (response.error) {
        this.$message.error(`上传失败: ${response.error.message}`)
      } else {
        this.uploadForm = {
          ...this.uploadForm,
          jarFileId: response.result?.data?.[0]?.id || null,
          jarFileName: response.result?.data?.[0]?.name || null
        }
      }
      this.jarFileLoading = false
      // 重置上传组件
      this.$nextTick(() => {
        this.$refs.jarUpload && this.$refs.jarUpload.clearFiles()
      })
    },
    dialogCancel() {
      this.$refs.uploadForm.resetFields()
      this.uploadDialogVisible = false
    },
    // 提交上传
    submitUpload() {
      if (!this.uploadForm.jarFileId && !this.uploadForm.viewFileId) {
        this.$message.warning('请至少上传一个文件')
        return
      }
      let that = this
      let params = JSON.stringify({
        id: this.uploadForm.id,
        jar_file_id: this.uploadForm.jarFileId,
        view_file_id: this.uploadForm.viewFileId
      })
      $.ajax({
        url: this.baseUrl + '/recovery/app/save',
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: that.tokenStorage
        },
        data: params,
        success: function (response) {
          if (response?.error) {
            that.$message.error(response?.error?.message)
          } else {
            that.$message.success('上传成功')
            that.uploadDialogVisible = false
            that.fetchData()
          }
        },
        error: function (xhr, status, error) {
          that.$message.error(error)
        }
      })
    }
  }
})
